-- Ensure the media bucket exists and can serve public website images.
values ('site-media', 'site-media', true)
on conflict (id) do update set public = true;

-- EzyGo starter content: 44 editable visa options + 2 editable travel packages.
-- Records are prebuilt, but media is intentionally NOT stored in GitHub.
-- Use Admin -> Starter media after seeding to upload the supplied local media folder into Supabase Storage.
begin;
grant usage on schema public to anon, service_role;
grant select on public.visa_groups, public.visa_cards, public.packages, public.galleries to anon;
grant insert on public.feedback to anon;
grant select, insert, update, delete on public.visa_groups, public.visa_cards, public.packages, public.galleries, public.feedback to service_role;
commit;
