insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('lakshadweep-3n4d','Lakshadweep - 3 Nights & 4 Days','Island package','Agatti Island · Lakshadweep','3 Nights · 4 Days','','A relaxed Lakshadweep island package built around Agatti sightseeing, lagoon experiences, boat activities and snorkelling. Final activity timing is subject to weather and local operating conditions.','["Agatti Island", "Local island sightseeing", "Scuba diving / water activities", "Kayaking", "Snorkelling", "Boat ride", "Island visits"]'::jsonb,'[{"day": 1, "title": "Arrival & Agatti local sightseeing", "meal": "Lunch · Dinner", "text": "Arrive at Agatti Island Airport and transfer to the stay. Check in, relax and get familiar with the surroundings. After lunch, explore the island with local sightseeing such as Kacheri Jetty, Lagoon Beach, Eastern Jetty and Andhan Beach. Dinner and overnight stay at Agatti Island."}, {"day": 2, "title": "Agatti island experience", "meal": "Lunch · Dinner", "text": "Continue the Agatti island experience with local sightseeing, relaxed beach and lagoon time, and activities based on local operations. Confirm the exact Day 2 activity schedule before publishing."}, {"day": 3, "title": "Boat trip, snorkelling & dolphin watch", "meal": "Breakfast · Lunch · Dinner", "text": "After breakfast, enjoy a boat trip and snorkelling. Lunch is planned on the boat in the middle of the sea. Return to Agatti for the overnight stay. Highlight of the day: dolphin watch and snorkelling."}, {"day": 4, "title": "Departure", "meal": "Breakfast", "text": "Breakfast at the stay, check out and proceed to the airport for the flight back home with memories of Lakshadweep."}]'::jsonb,'["Accommodation / room stay", "Meals as shown in the day-wise itinerary", "Local island sightseeing", "Boat trip / snorkelling activities as scheduled", "Local trip coordination and island visit support"]'::jsonb,'["Flights unless specifically confirmed", "Personal expenses", "Activities or services not listed in the final confirmation", "Extra charges caused by weather, sea conditions or operational changes"]'::jsonb,'["Final availability is subject to travel dates and confirmation.", "Water activities may change due to weather, sea conditions or local restrictions.", "Exact inclusions and timings should be reconfirmed before publishing or collecting payment."]'::jsonb,'','[]'::jsonb,0,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price=excluded.price,summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,sort_order=excluded.sort_order,active=true;
insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('delhi-manali-5n6d','Delhi + Manali - 5 Nights & 6 Days','Group tour','Delhi · Manali · Solang · Kullu','5 Nights · 6 Days','','A Delhi and Manali group itinerary combining Delhi sightseeing, Manali local attractions, the Rohtang / Solang route, Kullu sightseeing and Volvo travel.','["Jama Masjid", "Chandni Chowk", "Red Fort photo stop", "Hadimba Temple", "Solang Valley", "Atal Tunnel", "Kullu", "Volvo transfers"]'::jsonb,'[{"day": 1, "title": "Arrival & Delhi sightseeing", "meal": "As arranged", "text": "Pickup at the railway station and Delhi sightseeing. Visit Jama Masjid, Chandni Chowk for local shopping and street food, and Red Fort for an exterior/photo stop. Return to the railway station and continue to Manali by Volvo."}, {"day": 2, "title": "Manali local sightseeing", "meal": "Dinner", "text": "Arrival in Manali and transfer to the hotel. Early check-in is subject to availability. After freshening up, enjoy a half-day Manali local tour covering Hadimba Temple, Van Vihar Park and Tibetan Buddhist Monastery, followed by shopping at Mall Road. Dinner and stay at the hotel."}, {"day": 3, "title": "Rohtang / Solang full-day tour", "meal": "Breakfast · Dinner", "text": "After breakfast, proceed for a full-day tour towards Rohtang Pass, with Atal Tunnel and Solang Valley en route. Optional adventure activities such as cable car, zipline, skiing, sledge, horse/yak ride and ATV bike are at own cost. Return to the hotel for dinner and overnight stay."}, {"day": 4, "title": "Kullu & overnight Volvo", "meal": "Breakfast", "text": "After breakfast, check out. Visit Kullu for optional river rafting and paragliding, Kullu Vaishno Devi Temple, Kullu Shawl Factory and shopping. Evening drop at the Volvo pickup point and board the A/C semi-sleeper Volvo for the overnight journey to Delhi."}, {"day": 5, "title": "Reach Delhi", "meal": "—", "text": "Reach Delhi by morning. The supplied quotation lists the overall duration as 5 Nights / 6 Days and provides detailed day-wise activities through Day 5; confirm the final departure schedule before publishing."}]'::jsonb,'["2 nights accommodation at a 3-star hotel in Manali", "MAP meal basis: 2 breakfasts and 2 dinners", "1 day Delhi sightseeing", "3 days sightseeing at Manali", "Up and down Volvo travel"]'::jsonb,'["Train or flight fare", "Meals other than those mentioned in inclusions", "Personal expenses", "Entry fees for monuments, gondola, camera and adventure activities", "Room heater, snow dress, beverages, laundry, porter and tips", "River rafting, paragliding, snow activities and other adventure costs", "Extra 4x4 / snow vehicle charges during heavy snowfall", "Expenses caused by strikes, roadblocks, weather or natural calamities", "Services not mentioned in inclusions"]'::jsonb,'["Bookings are subject to availability and written confirmation.", "Rates and services can change based on travel dates, seasonality, hotel availability and transport revisions.", "Cancellation and amendment charges depend on the relevant service provider.", "No refund is normally provided for unused services due to no-show or late arrival.", "Final day-wise schedule should be reconfirmed before publishing."]'::jsonb,'','[]'::jsonb,1,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price=excluded.price,summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,sort_order=excluded.sort_order,active=true;
